import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { LayoutDashboard, Calendar, Heart, User } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { MOCK_VIEWING_REQUESTS, MOCK_PROPERTIES, REQUEST_STATUS_LABELS } from '../../data/mockData';
import PropertyCard from '../../components/PropertyCard';
import '../agent/AgentDashboard.css';

const TABS = [
  { id: 'overview', label: 'Overview', icon: <LayoutDashboard size={16} /> },
  { id: 'requests', label: 'My Viewings', icon: <Calendar size={16} /> },
  { id: 'wishlist', label: 'Wishlist', icon: <Heart size={16} /> },
  { id: 'profile', label: 'Profile', icon: <User size={16} /> },
];

export default function ClientDashboard() {
  const { user } = useAuth();
  const [tab, setTab] = useState('overview');
  const [wishlist] = useState(() => {
    const saved = localStorage.getItem('propconnect_wishlist');
    return saved ? JSON.parse(saved) : [];
  });

  const myRequests = MOCK_VIEWING_REQUESTS.filter(r => r.clientEmail === (user?.email || 'thabo@email.com'));
  const wishlistProperties = MOCK_PROPERTIES.filter(p => wishlist.includes(p.id));

  return (
    <div className="dashboard">
      <div className="dashboard-sidebar">
        <div className="sidebar-profile">
          <div className="sidebar-avatar">{user?.name?.charAt(0)}</div>
          <div>
            <div className="sidebar-name">{user?.name}</div>
            <div className="sidebar-role">Client</div>
          </div>
        </div>
        <nav className="sidebar-nav">
          {TABS.map(t => (
            <button key={t.id} className={`sidebar-link ${tab === t.id ? 'active' : ''}`} onClick={() => setTab(t.id)}>
              {t.icon} {t.label}
            </button>
          ))}
        </nav>
      </div>

      <div className="dashboard-content">
        {tab === 'overview' && (
          <div>
            <div className="dash-header">
              <div>
                <h1>Welcome, {user?.name?.split(' ')[0]}</h1>
                <p>Track your viewing requests and saved properties</p>
              </div>
              <Link to="/listings" className="btn btn-primary">Browse Listings</Link>
            </div>
            <div className="grid-4" style={{ marginBottom: '2rem' }}>
              {[
                { label: 'Viewing Requests', value: myRequests.length, color: '#e0f2fe', iconColor: '#0284c7' },
                { label: 'Pending', value: myRequests.filter(r => r.status === 'pending').length, color: '#fef3c7', iconColor: '#d97706' },
                { label: 'Confirmed', value: myRequests.filter(r => r.status === 'confirmed').length, color: '#dcfce7', iconColor: '#16a34a' },
                { label: 'Saved Properties', value: wishlist.length, color: '#fee2e2', iconColor: '#dc2626' },
              ].map(s => (
                <div key={s.label} className="stat-card">
                  <div className="stat-icon" style={{ background: s.color, color: s.iconColor }}>
                    <LayoutDashboard size={22} />
                  </div>
                  <div>
                    <div className="stat-value">{s.value}</div>
                    <div className="stat-label">{s.label}</div>
                  </div>
                </div>
              ))}
            </div>

            {myRequests.length > 0 && (
              <div className="card" style={{ padding: '1.5rem' }}>
                <div className="card-section-header">
                  <h3>Recent Viewing Requests</h3>
                  <button className="btn btn-ghost btn-sm" onClick={() => setTab('requests')}>View All</button>
                </div>
                <div className="table-wrapper">
                  <table>
                    <thead><tr><th>Property</th><th>Date & Time</th><th>Status</th></tr></thead>
                    <tbody>
                      {myRequests.map(r => {
                        const s = REQUEST_STATUS_LABELS[r.status];
                        return (
                          <tr key={r.id}>
                            <td><div className="table-title">{r.propertyTitle}</div></td>
                            <td>{r.preferredDate} at {r.preferredTime}</td>
                            <td><span className={`badge ${s.cls}`}>{s.label}</span></td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        )}

        {tab === 'requests' && (
          <div>
            <div className="dash-header">
              <div><h1>My Viewing Requests</h1><p>Track the status of your property viewings</p></div>
            </div>
            {myRequests.length === 0 ? (
              <div className="empty-state">
                <Calendar size={48} />
                <h3>No viewing requests yet</h3>
                <p>Browse listings and request a viewing to get started</p>
                <Link to="/listings" className="btn btn-primary" style={{ marginTop: '1rem' }}>Browse Listings</Link>
              </div>
            ) : (
              <div className="requests-list">
                {myRequests.map(r => {
                  const s = REQUEST_STATUS_LABELS[r.status];
                  return (
                    <div key={r.id} className="card request-card">
                      <div className="request-card-header">
                        <div>
                          <div className="request-client-name">{r.propertyTitle}</div>
                          <div className="request-property">Submitted on {r.createdAt}</div>
                        </div>
                        <span className={`badge ${s.cls}`}>{s.label}</span>
                      </div>
                      <div className="request-details">
                        <span><Calendar size={14} /> {r.preferredDate} at {r.preferredTime}</span>
                      </div>
                      {r.message && <p className="request-message">"{r.message}"</p>}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {tab === 'wishlist' && (
          <div>
            <div className="dash-header">
              <div><h1>Saved Properties</h1><p>Properties you've saved to your wishlist</p></div>
            </div>
            {wishlistProperties.length === 0 ? (
              <div className="empty-state">
                <Heart size={48} />
                <h3>No saved properties</h3>
                <p>Click the heart icon on any listing to save it here</p>
                <Link to="/listings" className="btn btn-primary" style={{ marginTop: '1rem' }}>Browse Listings</Link>
              </div>
            ) : (
              <div className="grid-3">
                {wishlistProperties.map(p => <PropertyCard key={p.id} property={p} />)}
              </div>
            )}
          </div>
        )}

        {tab === 'profile' && (
          <div>
            <div className="dash-header">
              <div><h1>My Profile</h1><p>Manage your account details</p></div>
            </div>
            <div className="card" style={{ padding: '2rem', maxWidth: 520 }}>
              <div className="profile-avatar-row">
                <div className="profile-avatar">{user?.name?.charAt(0)}</div>
                <div>
                  <h3>{user?.name}</h3>
                  <p style={{ color: 'var(--text-muted)', fontSize: '0.88rem' }}>Client Account</p>
                </div>
              </div>
              <div className="form-group" style={{ marginTop: '1.5rem' }}>
                <label>Full Name</label>
                <input className="form-control" defaultValue={user?.name} />
              </div>
              <div className="form-group">
                <label>Email Address</label>
                <input className="form-control" type="email" defaultValue={user?.email} />
              </div>
              <div className="form-group">
                <label>Phone Number</label>
                <input className="form-control" defaultValue={user?.phone || ''} placeholder="07x xxx xxxx" />
              </div>
              <button className="btn btn-primary">Save Changes</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
